import logging

from ...templatesession import new_session
from .base_btssm import BaseBtssmInterface

logger = logging.getLogger(__name__)


class ScfcInterface(BaseBtssmInterface):
    """Keywords related to SCFC validation."""

    def validate_scfc(self, scfc_file, feedback_file, **kwargs):
        """*DEPRECATED*
        Please use validate_scfc in ute_scfc. Refer to http://doc.ute.inside.nsn.com/packages/ute_scfc/interfaces/ute_scfc.html
        """
        logger.warning('DEPRECATED. Please use validate_scfc in ute_scfc.')
        scfc_file = scfc_file.strip() if scfc_file is not None else None
        feedback_file = feedback_file.strip() if feedback_file is not None else None
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        config = self.command_store.get(alias).get_config()
        with new_session.NewSession(alias, config) as session:
            self._generate_feedback_file(session.scfc.validator, scfc_file, feedback_file)
            session.scfc.validator.check_validation_result(feedback_file)

    def generate_validation_report(self, scfc_file, feedback_file, **kwargs):
        """*DEPRECATED*
        Please use generate_validation_report in ute_scfc. Refer to http://doc.ute.inside.nsn.com/packages/ute_scfc/interfaces/ute_scfc.html
        """
        logger.warning('DEPRECATED. Please use generate_validation_report in ute_scfc.')
        scfc_file = scfc_file.strip() if scfc_file is not None else None
        feedback_file = feedback_file.strip() if feedback_file is not None else None
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        config = self.command_store.get(alias).get_config()
        with new_session.NewSession(alias, config) as session:
            self._generate_feedback_file(session.scfc.validator, scfc_file, feedback_file)

    def fix_scfc_errors(self, input_scfc, output_scfc, feedback_file, dictionary_file, **kwargs):
        """*DEPRECATED*
        Please use fix_scfc_errors in ute_scfc. Refer to http://doc.ute.inside.nsn.com/packages/ute_scfc/interfaces/ute_scfc.html
        """
        logger.warning('DEPRECATED. Please use fix_scfc_errors in ute_scfc.')
        input_scfc = input_scfc.strip() if input_scfc is not None else None
        output_scfc = output_scfc.strip() if output_scfc is not None else None
        feedback_file = feedback_file.strip() if feedback_file is not None else None
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        config = self.command_store.get(alias).get_config()
        with new_session.NewSession(alias, config) as session:
            session.scfc.fixer.fix_scfc_errors(input_scfc, output_scfc, feedback_file, dictionary_file)

    def migrate_scfc_using_sutool(self, scfc_path, output_path, scfds_source='active partition', ignore_errors=True, **kwargs):
        """*DEPRECATED*
        Please use migrate_scfc_using_sutool in ute_scfc. Refer to http://doc.ute.inside.nsn.com/packages/ute_scfc/interfaces/ute_scfc.html
        """
        logger.warning('DEPRECATED. Please use migrate_scfc_using_sutool in ute_scfc.')
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        config = self.command_store.get(alias).get_config()
        with new_session.NewSession(alias, config) as session:
            log_path = '{path}{sep}'.format(path=session.log_path, sep='/' if not session.log_path.endswith('/') else '')
            return session.scfc.fixer.migrate_scfc_using_sutool(scfc_path, output_path, scfds_source, enb_ip=session.trs_ip,
                                                                log_path=log_path, ignore_errors=ignore_errors)

    def _generate_feedback_file(self, validator, scfc_file, feedback_file):
        version = validator.get_version(scfc_file)
        new_path = validator.copy_scfc(scfc_file)
        feedback = validator.run_validation(new_path, version)
        return validator.get_file(feedback, feedback_file)
